using System.Text;
using VisualRelay.Domain;

namespace VisualRelay.Core.Execution;

// Task-input existence gate, split out of RelayDriver.cs to keep it under the
// 300-line guard. Hard-fails a run whose task input is missing or empty before
// any stage executes, preventing the defect where eight stages silently ran
// against an empty prompt and fabricated a plausible task from the folder slug.
public sealed partial class RelayDriver
{
    /// <summary>
    /// Returns <c>null</c> (no-op) when <paramref name="task"/> is non-null and
    /// <paramref name="input"/>.Markdown is not whitespace-only. Otherwise fails
    /// the run before any stage executes: writes NEEDS-REVIEW, publishes an error
    /// event, persists status, and returns a Flagged outcome.
    /// </summary>
    private async Task<RelayTaskOutcome?> FailIfTaskInputMissingAsync(
        RelayTaskItem? task,
        RelayTaskInput input,
        string rootPath,
        string runId,
        string taskId,
        string taskDirectory,
        StringBuilder ledger,
        List<StageStatusEntry> statusEntries,
        CancellationToken cancellationToken)
    {
        if (task is not null && !string.IsNullOrWhiteSpace(input.Markdown))
            return null;

        const string reason = "task spec missing or empty at run start — refusing to run stages against an empty input";

        // Write NEEDS-REVIEW so the queue UI surfaces a red card with the reason.
        try
        {
            Directory.CreateDirectory(taskDirectory);
            await File.WriteAllTextAsync(
                Path.Combine(taskDirectory, "NEEDS-REVIEW"),
                reason + Environment.NewLine,
                cancellationToken);
        }
        catch (OperationCanceledException) { throw; }
        catch { /* best-effort marker */ }

        // Publish an error event so the drain log records why nothing ran.
        try
        {
            await _dependencies.EventSink.PublishAsync(
                new RelayEvent(DateTimeOffset.UtcNow, "error", "empty_task_input",
                    runId, rootPath, taskId, Data: new Dictionary<string, string>
                    {
                        ["reason"] = reason
                    }),
                cancellationToken);
        }
        catch (OperationCanceledException) { throw; }
        catch { /* best-effort event */ }

        // Persist status and return a failed outcome mirroring
        // RestoreFlaggedWorkIfNeededAsync's early-return construction.
        MarkStatusFlagged(statusEntries, 1, reason);
        await WriteStatusAsync(taskDirectory, statusEntries, cancellationToken);

        return new RelayTaskOutcome(taskId, RelayTaskOutcomeStatus.Flagged, null, null, reason);
    }
}

